<?php $_GET["scope"] = "trend"; $_GET["start_year"] = 2016; $_GET["end_year"] = 2025; $_GET["area"] = "All Areas"; $_GET["force_refresh"] = 1; ob_start(); require_once __DIR__ . "/api/get_ecological_data.php"; $output = ob_get_clean(); $data = json_decode($output, true); if ($data && isset($data["trend_data"])) { $td = $data["trend_data"]; $v3 = array_slice($td["viirs"] ?? [], 0, 3); $n3 = array_slice($td["ndvi"] ?? [], 0, 3); $l3 = array_slice($td["lst"] ?? [], 0, 3); echo "VIIRS (first 3): " . json_encode($v3) . "\n"; echo "NDVI (first 3): " . json_encode($n3) . "\n"; echo "LST (first 3): " . json_encode($l3) . "\n"; echo "Correlations: VIIRS-NDVI: " . ($td["correlation_viirs_ndvi"] ?? "N/A") . ", VIIRS-LST: " . ($td["correlation_viirs_lst"] ?? "N/A") . "\n"; } else { echo "Error: Could not retrieve trend data.\n"; echo "Raw output snippet: " . substr($output, 0, 500) . "\n"; }
